use mdc_core::contract::registry::*;
use mdc_core::identity::{CanonicalSemanticBasis,IdentityAdapter};
use mdc_core::pipeline::*;
fn r(s:&str)->VersionedId { VersionedId::new(s,1).unwrap() }
fn emit<T:CanonicalSemanticBasis>(name:&str,value:&T) {
    let basis=value.canonical_basis();
    print!("{}:{}:",name,IdentityAdapter::derive_identity(value));
    for byte in basis {print!("{byte:02x}");}
    println!();
}
fn main() {
 let mut registry=Registry::new();
 registry.register_schema(SchemaContract{reference:r("schema"),format:ScalarSchema::SignedI64Le}).unwrap();
 registry.register_source(SourceContract{reference:r("source"),schema:r("schema"),context:DomainContext::new("fixture",r("tick")).unwrap(),unit:"count".into()}).unwrap();
 registry.register_operator(OperatorContract{reference:r("read"),kind:OperatorKind::Scalar}).unwrap();
 registry.register_operator(OperatorContract{reference:r("difference"),kind:OperatorKind::Difference}).unwrap();
 let mut pipeline=Pipeline::new(registry);
 let a=pipeline.admit(ObservationRequest{source:r("source"),timestamp:Some(10),payload:17_i64.to_le_bytes().to_vec(),acquisition_context:"record-a".into()}).unwrap();
 let b=pipeline.admit(ObservationRequest{source:r("source"),timestamp:Some(20),payload:5_i64.to_le_bytes().to_vec(),acquisition_context:"record-b".into()}).unwrap();
 let ma=pipeline.measure(MeasurementRequest{operator:r("read"),inputs:vec![a.clone()]}).unwrap();
 let mb=pipeline.measure(MeasurementRequest{operator:r("read"),inputs:vec![b.clone()]}).unwrap();
 let delta=pipeline.measure(MeasurementRequest{operator:r("difference"),inputs:vec![ma.clone(),mb.clone()]}).unwrap();
 emit("O_A",pipeline.resolve_observation(&a).unwrap());
 emit("O_B",pipeline.resolve_observation(&b).unwrap());
 emit("M_A",pipeline.resolve_measurement(&ma).unwrap());
 emit("M_B",pipeline.resolve_measurement(&mb).unwrap());
 emit("M_DELTA",pipeline.resolve_measurement(&delta).unwrap());
 println!("TRACE:{:?}",pipeline.trace(&delta).unwrap());
}
